int main() {
    vector<long long> pos[10];
    long long cnt2 = -1, n;
    long long pw[15], s[15] = {0};
    int result = 0, total_count = 0;

    auto query = [&](int fixpre, int val) {
        long long total = 0;
        for (int d = 0; d < 7; ++d) {
            long long offset = (val - fixpre * pw[d]) % 998244353;
            if (offset < 0) offset += 998244353;
            int p = (int)(lower_bound(pos[d].begin(), pos[d].end(), 998244353 - offset) - pos[d].begin());
            total = (total + s[d] + offset * (int)pos[d].size() - 998244353 * ((int)pos[d].size() - p)) % 998244353;
        }
        return total;
    };

    function<void(long long, int)> dfs = [&](long long val, int d) {
        int x = (total_count - val + 998244353) % 998244353;
        pos[d].push_back(x);
        total_count++;
        s[d] += x;
        if (d == 6) return;
        for (int i = 0; i < 10; ++i) {
            dfs(val * 10 + i, d + 1);
        }
    };

    function<void(long long)> dfs2 = [&](long long val) {
        if (val * 1000000 + 999999 <= n && val * 10000000 > n) {
            result = (result + query(val, cnt2 + 1)) % 998244353;
            cnt2 += total_count;
        } else {
            cnt2++;
            result = (result + ((cnt2 - val) % 998244353 + 998244353) % 998244353) % 998244353;
            for (int i = (val ? 0 : 1); i < 10; ++i) {
                if (val * 10 + i <= n) dfs2(val * 10 + i);
            }
        }
    };

    cin >> n;
    for (int i = 0; i < 7; ++i) sort(pos[i].begin(), pos[i].end());
    pw[0] = 1;
    for (int i = 1; i < 13; ++i) pw[i] = pw[i - 1] * 10;

    dfs(0, 0);
    dfs2(0);
    cout << result << "\n";

    return 0;
}
